#include <print>
#include <stack>
#include <string>

char partner(char c) {
    if (c == ')') return '(';
    if (c == ']') return '[';
    if (c == '}') return '{';
    return 0;
}

bool ok3(const std::string& s) {
    std::stack<char> left;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') left.push(c);
        else if (char p = partner(c)) {
            if (left.empty() || left.top() != p) return false;
            left.pop();
        }
    }
    return left.empty();
}

int main() {
    for (std::string s : {"(()())", "([)]", "[("})
        std::println("{} -> {}", s, ok3(s) ? "匹配" : "不匹配");
    int n = 13;
    std::stack<int> bits;
    do {
        bits.push(n % 2);
        n /= 2;
    } while (n > 0);
    while (!bits.empty()) { std::print("{}", bits.top()); bits.pop(); }
    std::println("");
    return 0;
}

